<?php declare(strict_types=1);require_once __DIR__.'/includes/auth.php';$merchant=require_login();$id=substr((string)($_GET['order_id']??''),0,32);$q=db()->prepare("SELECT order_id,amount,payable_amount,utr,paid_at,created_at FROM orders WHERE merchant_id=? AND order_id=? AND status='success'");$q->execute([$merchant['id'],$id]);$o=$q->fetch();if(!$o){http_response_code(404);exit('Invoice unavailable');}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Payment receipt <?=h($o['order_id'])?></title><link rel="stylesheet" href="/assets/css/design-system.css"><link rel="stylesheet" href="/assets/css/marketing.css"><style>.receipt{max-width:650px;margin:60px auto;background:white;border:1px solid var(--line);padding:40px;border-radius:14px}.receipt dl{display:grid;grid-template-columns:1fr 1fr;gap:12px}.receipt dt{color:var(--muted)}@media print{.no-print{display:none}.receipt{margin:0;border:0}}</style></head><body><article class="receipt"><a class="brand" href="/dashboard.php"><img src="/assets/img/logo.svg" alt="">TG Gateways</a><h1>Payment receipt</h1><p>Merchant: <?=h($merchant['name'])?></p><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><dl><dt>Order ID</dt><dd><?=h($o['order_id'])?></dd><dt>Amount</dt><dd>₹<?=number_format((float)$o['amount'],2)?> INR</dd><dt>Payment status</dt><dd>Successful</dd><dt>UTR</dt><dd><?=h($o['utr']?:'—')?></dd><dt>Paid at</dt><dd><?=h($o['paid_at']?:'—')?></dd></dl><p style="color:var(--muted);font-size:11px">This receipt reflects a payment status recorded by TG Gateways and is not a tax invoice.</p><button class="btn no-print" onclick="window.print()">Print / Save as PDF</button></article></body></html>
